from collections import defaultdict
from typing import List
DEBUG = False

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # if DEBUG:
        #     endOf = [0] * n # for debug
        endOfCount = defaultdict(lambda: 0)
        
        result = 0
        prefix = 0
        for i in range(n):
            prefix += nums[i]

            if prefix == k:  # the substr ends with nums[i] is one answer
                result += 1

            # look for x where 
            #   1) x < i 
            #   2) endOf[i] - endOf[x] == k, i.e. endOf[x] = endOf[i] - k
            # endOfCount[*] = 0 by default
            result += endOfCount[prefix-k]     
            # if DEBUG:
            #     endOf[i] = prefix
            endOfCount[prefix] = endOfCount[prefix] + 1

        return result

if __name__ == "__main__":
    import time

    sol = Solution()

    def computeExpected(nums, k):
        # compute expected using brute force
        n = len(nums)
        count = 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                if s == k:
                    count += 1
        return count
